def get_dropdown_templates():
    """Get all dropdown templates - merges defaults with user-saved templates.

    Built-in default templates are always included and can be customized.
    User-added templates are preserved separately.
    """
    import json

    # Start with a copy of defaults (these will always be present)
    default_ids = set(t['id'] for t in DEFAULT_DROPDOWN_TEMPLATES)
    result = list(DEFAULT_DROPDOWN_TEMPLATES)  # Copy of defaults

    try:
        stored = model.TextContent(DROPDOWN_TEMPLATES_STORAGE_KEY)
        if stored:
            stored_templates = json.loads(stored)
            stored_by_id = {t['id']: t for t in stored_templates}

            # Update defaults with any customizations from stored
            for i, t in enumerate(result):
                if t['id'] in stored_by_id:
                    # User customized this default template - use their version
                    result[i] = stored_by_id[t['id']]

            # Add any user-created templates (not in defaults)
            for t in stored_templates:
                if t['id'] not in default_ids:
                    result.append(t)
    except:
        pass

    return result


def save_dropdown_templates(templates):
    """Save dropdown templates to storage."""
    import json
    try:
        model.WriteContentText(DROPDOWN_TEMPLATES_STORAGE_KEY, safe_json(templates), "")
        return True
    except:
        return False


# Id of the template used for the approval notification. This template is the SINGLE
# source of that email's wording -- the approval prompt is handed it by the server
# rather than keeping its own copy, because a second copy is exactly what made edits
# to the template look like they were being ignored.
APPROVAL_TEMPLATE_ID = 'approval_notification'


def get_approval_email_template():
    """The 'Registration Approved' subject/body, with placeholders unresolved.

    get_dropdown_templates() always yields this id: the user's saved version if they
    customised it under Settings > Quick Email Templates, otherwise the built-in
    default. Returns empty strings only if the template genuinely cannot be read, which
    the prompt surfaces rather than silently substituting different wording.
    """
    try:
        for t in get_dropdown_templates():
            if t.get('id') == APPROVAL_TEMPLATE_ID:
                return {
                    'subject': t.get('subject') or '',
                    'body': t.get('body') or '',
                }
    except:
        pass
    return {'subject': '', 'body': ''}


